// IO_LINK_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module IO_LINK_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic  c_cfg_master,
  input logic [1:0] c_cfg_mtype,
  input logic [3:0] c_cfg_ta,
  input logic  c_cfg_event,
  input logic  c_cfg_pd_invalid,
  input logic [15:0] c_cfg_bit,
  input logic [15:0] c_cfg_wurq,
  input logic [5:0] c_cfg_pdout_len,
  input logic [5:0] c_cfg_pdin_len,
  input logic [5:0] c_cfg_od_len,
  input logic [7:0] c_cfg_resp_timeout,
  input logic [7:0] c_m_mc,
  input logic [7:0] c_host_addr,
  input logic [7:0] c_host_wdata,
  input logic  c_m_start,
  input logic  c_m_wurq,
  input logic  c_host_wr,
  input logic  c_host_rd,
  input logic [7:0] c_host_rdata,
  input logic  c_m_busy,
  input logic  c_m_err_timeout,
  input logic  c_m_err_uart,
  input logic  c_m_err_cks,
  input logic [7:0] c_m_cks,
  input logic [6:0] c_m_cnt,
  input logic [7:0] c_d_msg_mc,
  input logic [2:0] c_d_msg_why,
  input logic  c_d_msg,
  input logic  c_m_done,
  input logic  c_d_wurq
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 15;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:14];          // model of every stored word
  logic [3:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;
  logic m_state_D_MSG;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_m_done) m_set[0] = 1'b1;
    if (c_d_wurq) m_set[1] = 1'b1;
    if (c_d_msg && !m_state_D_MSG) m_set[2] = 1'b1;
    if (c_d_msg && m_state_D_MSG && (m_rd && m_map && m_idx == 14)) m_set[2] = 1'b1;
    if (c_d_msg && m_state_D_MSG && !(m_rd && m_map && m_idx == 14)) m_set[3] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h10;
      m_w[6] <= 32'hFA000D9;
      m_w[7] <= 32'h401000;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_pulse_CMD <= 0;
      m_state_D_MSG <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'hF;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h1FF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'h3FFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 11) ? PWDATA & m_be & 32'hF : 0;
      if (c_d_msg && (!m_state_D_MSG || (m_rd && m_map && m_idx == 14))) begin
        m_w[14] <= (32'(c_d_msg_mc[7:0]) << 0) | (32'(c_d_msg_why[2:0]) << 8);
        m_state_D_MSG <= 1;
      end else if ((m_rd && m_map && m_idx == 14)) m_state_D_MSG <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h10C90100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_D_MSG});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return 0;
      12: return (32'(c_host_rdata) << 0);
      13: return (32'(c_m_busy) << 0) | (32'(c_m_err_timeout) << 1) | (32'(c_m_err_uart) << 2) | (32'(c_m_err_cks) << 3) | (32'(c_m_cks) << 4) | (32'(c_m_cnt) << 12);
      14: return m_w[14];
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][3:0] & m_w[2][3:0]))
  `SVA_INV(a_core_cfg_master, c_cfg_master == m_w[5][0:0])
  `SVA_INV(a_core_cfg_mtype, c_cfg_mtype == m_w[5][2:1])
  `SVA_INV(a_core_cfg_ta, c_cfg_ta == m_w[5][6:3])
  `SVA_INV(a_core_cfg_event, c_cfg_event == m_w[5][7:7])
  `SVA_INV(a_core_cfg_pd_invalid, c_cfg_pd_invalid == m_w[5][8:8])
  `SVA_INV(a_core_cfg_bit, c_cfg_bit == m_w[6][15:0])
  `SVA_INV(a_core_cfg_wurq, c_cfg_wurq == m_w[6][31:16])
  `SVA_INV(a_core_cfg_pdout_len, c_cfg_pdout_len == m_w[7][5:0])
  `SVA_INV(a_core_cfg_pdin_len, c_cfg_pdin_len == m_w[7][11:6])
  `SVA_INV(a_core_cfg_od_len, c_cfg_od_len == m_w[7][17:12])
  `SVA_INV(a_core_cfg_resp_timeout, c_cfg_resp_timeout == m_w[7][25:18])
  `SVA_INV(a_core_m_mc, c_m_mc == m_w[8][7:0])
  `SVA_INV(a_core_host_addr, c_host_addr == m_w[9][7:0])
  `SVA_INV(a_core_host_wdata, c_host_wdata == m_w[10][7:0])
  `SVA_INV(a_core_m_start, c_m_start == m_pulse_CMD[0])
  `SVA_INV(a_core_m_wurq, c_m_wurq == m_pulse_CMD[1])
  `SVA_INV(a_core_host_wr, c_host_wr == m_pulse_CMD[2])
  `SVA_INV(a_core_host_rd, c_host_rd == m_pulse_CMD[3])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cfg_master == 1'h0 && c_cfg_mtype == 2'h0 && c_cfg_ta == 4'h2 && c_cfg_event == 1'h0 && c_cfg_pd_invalid == 1'h0 && c_cfg_bit == 16'hD9 && c_cfg_wurq == 16'hFA0 && c_cfg_pdout_len == 6'h0 && c_cfg_pdin_len == 6'h0 && c_cfg_od_len == 6'h1 && c_cfg_resp_timeout == 8'h10 && c_m_mc == 8'h0 && c_host_addr == 8'h0 && c_host_wdata == 8'h0 && c_m_start == 1'h0 && c_m_wurq == 1'h0 && c_host_wr == 1'h0 && c_host_rd == 1'h0)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 5)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 5)
  `FC(rd_TIMING, m_rd && m_map && m_idx == 6)
  `FC(wr_TIMING, m_wr && m_map && m_idx == 6)
  `FC(rd_LENGTHS, m_rd && m_map && m_idx == 7)
  `FC(wr_LENGTHS, m_wr && m_map && m_idx == 7)
  `FC(rd_MC, m_rd && m_map && m_idx == 8)
  `FC(wr_MC, m_wr && m_map && m_idx == 8)
  `FC(rd_MEM_ADDR, m_rd && m_map && m_idx == 9)
  `FC(wr_MEM_ADDR, m_wr && m_map && m_idx == 9)
  `FC(rd_MEM_WDATA, m_rd && m_map && m_idx == 10)
  `FC(wr_MEM_WDATA, m_wr && m_map && m_idx == 10)
  `FC(rd_CMD, m_rd && m_map && m_idx == 11)
  `FC(wr_CMD, m_wr && m_map && m_idx == 11)
  `FC(rd_MEM_RDATA, m_rd && m_map && m_idx == 12)
  `FC(wr_MEM_RDATA, m_wr && m_map && m_idx == 12)
  `FC(rd_M_STATUS, m_rd && m_map && m_idx == 13)
  `FC(wr_M_STATUS, m_wr && m_map && m_idx == 13)
  `FC(rd_D_MSG, m_rd && m_map && m_idx == 14)
  `FC(wr_D_MSG, m_wr && m_map && m_idx == 14)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_M_DONE_set, m_set[0])
  `FC(irq_M_DONE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_M_DONE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_M_DONE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_WURQ_set, m_set[1])
  `FC(irq_WURQ_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_WURQ_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_WURQ_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_D_MSG_AVAIL_set, m_set[2])
  `FC(irq_D_MSG_AVAIL_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_D_MSG_AVAIL_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_D_MSG_AVAIL_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_D_MSG_OVF_set, m_set[3])
  `FC(irq_D_MSG_OVF_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_D_MSG_OVF_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_D_MSG_OVF_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(cmd_m_start, m_pulse_CMD[0])
  `FC(cmd_m_wurq, m_pulse_CMD[1])
  `FC(cmd_host_wr, m_pulse_CMD[2])
  `FC(cmd_host_rd, m_pulse_CMD[3])
  `FC(D_MSG_capture, c_d_msg && !m_state_D_MSG)
  `FC(D_MSG_overflow, c_d_msg && m_state_D_MSG && !(m_rd && m_map && m_idx == 14))
  `FC(D_MSG_pop, m_rd && m_map && m_idx == 14 && m_state_D_MSG)
  `FC(D_MSG_read_empty, m_rd && m_map && m_idx == 14 && !m_state_D_MSG)
  `FC(D_MSG_pop_and_capture, c_d_msg && m_state_D_MSG && m_rd && m_map && m_idx == 14)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind IO_LINK_apb IO_LINK_apb_sva u_apb_sva (.*);
